import {createContext, createEffect, JSX, on, onCleanup, onMount, Ref, useContext} from 'solid-js';

import styles from '@components/chipTabs.module.scss';
import classNames from '@helpers/string/classNames';
import findUpClassName from '@helpers/dom/findUpClassName';
import {fastRaf} from '@helpers/schedulers';
import getVisibleRect from '@helpers/dom/getVisibleRect';
import Scrollable from '@components/scrollable2';
import fastSmoothScroll from '@helpers/fastSmoothScroll';
import createContextMenu from '@helpers/dom/createContextMenu';
import {ButtonMenuItemOptionsVerifiable} from '@components/buttonMenu';
import {handleTabKeyDown} from '@helpers/dom/tabList';
import Modes from '@config/modes';
import filterAsync from '../helpers/array/filterAsync';
import verifyMenuItem from '@helpers/verifyMenuItem';

interface ChipTabsContextValue {
  value: string,
  onClick: (event: MouseEvent, value: string) => void
}

const ChipTabsContext = createContext<ChipTabsContextValue>(null);

export function ChipTab(props: {
  class?: string
  children: JSX.Element
  value: string
}) {
  const ctx = useContext(ChipTabsContext);
  const selected = () => ctx.value === props.value;
  return (
    <div
      class={classNames(styles.chip, selected() && styles.active, props.class)}
      onClick={(event: MouseEvent) => ctx.onClick(event, props.value)}
      data-value={props.value}
      role="tab"
      aria-selected={selected()}
      tabindex={Modes.a11y ? (selected() ? 0 : -1) : undefined}
    >
      {props.children}
    </div>
  )
}

export function ChipTabs(props: {
  class?: string
  value: string,
  view: 'surface' | 'secondary' | 'primary',
  onChange: (value: string) => boolean | void,
  contextMenuButtons?: (itemId: string) => MaybePromise<ButtonMenuItemOptionsVerifiable[]>,
  children: JSX.Element
  ref?: Ref<HTMLDivElement>
  /** the row the chips are laid out in, which scrolls */
  scrollableRef?: (el: HTMLDivElement) => void
  center?: boolean
  needIntersectionObserver?: boolean
}) {
  let scrollable!: HTMLDivElement;
  let chosenRef!: HTMLDivElement;

  function updateChosen(categoryEl: HTMLElement, categoryRect: DOMRect) {
    const scrollableRect = scrollable.getBoundingClientRect();
    chosenRef.style.width = `${categoryRect.width}px`;
    chosenRef.style.left = `${categoryRect.left - scrollableRect.left + scrollable.scrollLeft}px`;

    const visibleRect = getVisibleRect(categoryEl, scrollable, false, categoryRect, undefined, true);
    if(!visibleRect || visibleRect.overflow.horizontal) {
      fastSmoothScroll({
        element: categoryEl,
        container: scrollable,
        position: 'center',
        axis: 'x'
      });
    }
  }

  function handleClick(event: MouseEvent, value: string) {
    const result = props.onChange(value);
    if(result === false) return;
    const categoryEl = findUpClassName(event.target as HTMLElement, styles.chip);

    fastRaf(() => {
      const categoryRect = categoryEl.getBoundingClientRect();
      updateChosen(categoryEl, categoryRect);
    });
  }

  let updatedOnce = false
  function updateCurrent() {
    const categoryEl = scrollable.querySelector(`[data-value="${props.value}"]`);
    if(categoryEl) {
      const rect = categoryEl.getBoundingClientRect();
      if(rect.width === 0 && rect.height === 0) return;
      updateChosen(categoryEl as HTMLElement, rect);
    }
    if(!updatedOnce) {
      chosenRef.classList.add(styles.animate);
      updatedOnce = true;
    }
  }

  createEffect(on(() => props.value, () => fastRaf(updateCurrent)))

  // * the chosen chip can also move without being chosen anew: when chips come before it, or the
  // * chips are put in another order
  onMount(() => {
    const observer = new MutationObserver(() => fastRaf(updateCurrent));
    observer.observe(scrollable, {childList: true});
    onCleanup(() => observer.disconnect());
  });

  if(props.needIntersectionObserver) {
    onMount(() => {
      const observer = new IntersectionObserver((mutations) => {
        mutations.forEach((mutation) => {
          if(mutation.isIntersecting) {
            updateCurrent();
            observer.disconnect();
          }
        });
      }, {
        threshold: 1
      });

      observer.observe(scrollable.parentElement);

      onCleanup(() => observer.disconnect());
    })
  }

  if(props.contextMenuButtons) {
    let chosenElement: HTMLElement;
    onMount(() => {
      createContextMenu({
        listenTo: scrollable,
        findElement: (event) => findUpClassName(event.target as HTMLElement, styles.chip),
        onOpen: (event, target) => {
          chosenElement = target;
        },
        buttons: [],
        filterButtons: async() => {
          const buttons = await props.contextMenuButtons(chosenElement.dataset.value)
          return filterAsync(buttons, verifyMenuItem)
        }
      })
    })
  }

  return (
    <ChipTabsContext.Provider
      value={{
        get value() {
          return props.value;
        },
        onClick: handleClick
      }}
    >
      <div
        class={classNames(
          props.class,
          styles.container,
          styles[props.view],
          props.view === 'primary' && styles.primary,
          props.center && styles.center
        )}
        ref={props.ref}
        role="tablist"
        onKeyDown={handleTabKeyDown}
      >
        <Scrollable
          axis="x"
          ref={(el) => {
            scrollable = el;
            props.scrollableRef?.(el);
          }}
          tabIndex={null}
        >
          <div class={styles.chosen} ref={chosenRef} aria-hidden="true" />
          {props.children}
        </Scrollable>
      </div>
    </ChipTabsContext.Provider>
  )
}
